        if not isinstance(self.batch_digest, bytes):
            raise TypeError(
                "journal batch receipt batch_digest must be bytes"
            )
        if len(self.batch_digest) != 32:
            raise ValueError(
                "journal batch receipt batch_digest must be exactly 32"
                " bytes"
            )
