    except TypeError:
        raise TypeError(
            "items must be an iterable of (receipt, range) pairs"
        ) from None
    if not pairs:
        raise ValueError("items must be a non-empty sequence")
    coerced = []
    for pair in pairs:
        try:
            raw_receipt, raw_range = pair
        except TypeError:
            raise TypeError(
                "items entries must be (receipt, range) pairs"
            ) from None
        except ValueError:
            raise ValueError(
                "items entries must be (receipt, range) pairs"
            ) from None
